import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/tmp/uploads'
os.makedirs(UPLOAD_DIR, exist_ok=True)

def sanitize_filename(name):
    """Remove directory traversal but allow special chars in filename."""
    return os.path.basename(name)

def convert_document(input_path, output_format):
    """Convert document using system utility."""
    output_path = input_path + '.' + output_format
    # Uses pandoc for document conversion
    cmd = f'pandoc {input_path} -o {output_path} --pdf-engine=xelatex'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
    return output_path, result.returncode, result.stderr.decode()

def extract_metadata(filepath):
    """Extract document metadata using exiftool."""
    cmd = f'exiftool -json {filepath}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=10)
    return result.stdout.decode()

@app.route('/api/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    output_format = request.form.get('format', 'pdf')

    # Validate output format
    allowed_formats = ['pdf', 'docx', 'html', 'txt', 'odt']
    if output_format not in allowed_formats:
        return jsonify({'error': 'Unsupported format'}), 400

    filename = sanitize_filename(uploaded.filename)
    filepath = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(filepath)

    # Extract metadata first
    metadata = extract_metadata(filepath)

    # Convert document
    output_path, retcode, stderr = convert_document(filepath, output_format)

    if retcode != 0:
        return jsonify({'error': 'Conversion failed', 'details': stderr}), 500

    return jsonify({
        'status': 'success',
        'output': output_path,
        'metadata': metadata
    })

@app.route('/api/metadata', methods=['POST'])
def metadata():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = sanitize_filename(uploaded.filename)
    filepath = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(filepath)

    metadata = extract_metadata(filepath)
    return jsonify({'metadata': metadata})

@app.route('/api/batch', methods=['POST'])
def batch_convert():
    """Batch convert with custom pandoc args for power users."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    extra_args = request.form.get('pandoc_args', '')
    output_format = request.form.get('format', 'pdf')

    filename = sanitize_filename(uploaded.filename)
    filepath = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(filepath)

    output_path = filepath + '.' + output_format
    cmd = f'pandoc {filepath} -o {output_path} {extra_args}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=60)

    if result.returncode != 0:
        return jsonify({'error': 'Conversion failed', 'details': result.stderr.decode()}), 500

    return jsonify({'status': 'success', 'output': output_path})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
